// RunnirCoreServer is the server API for RunnirCore service.
// All implementations must embed UnimplementedRunnirCoreServer
// for forward compatibility.
type RunnirCoreServer interface {
	HealthCheck(context.Context, *HealthCheckRequest) (*HealthCheckResponse, error)
	// Idempotent per resolved path: reopening returns the existing context.
	OpenRepository(context.Context, *OpenRepositoryRequest) (*RepositoryResponse, error)
	CloseRepository(context.Context, *CloseRepositoryRequest) (*CloseRepositoryResponse, error)
	RefreshRepository(context.Context, *RefreshRepositoryRequest) (*RepositoryResponse, error)
	// A workspace's GitHub activity as cached on this Mac: the newest runs,
	// the workflows and how fresh they are. Never waits for GitHub. Needs a
	// repository opened with a workspace_id (FAILED_PRECONDITION otherwise).
	GetWorkspaceActivity(context.Context, *GetWorkspaceActivityRequest) (*WorkspaceActivity, error)
	// Asks the workspace's sync for a pass; requests during a pass are merged
	// into one more. With wait, answers after a pass that started after the
	// request ended.
	RefreshWorkspaceActivity(context.Context, *RefreshWorkspaceActivityRequest) (*WorkspaceActivity, error)
	// Reads one page of runs older than the oldest cached one from GitHub and
	// stores it; nothing is read when the cache holds 5000 runs or the whole
	// history. Concurrent calls for one workspace share one request.
	LoadOlderRuns(context.Context, *LoadOlderRunsRequest) (*LoadOlderRunsResponse, error)
	// What workspaces keep on this Mac, by id; empty ids: every workspace with
	// data and every open one.
	GetStorageUsage(context.Context, *GetStorageUsageRequest) (*GetStorageUsageResponse, error)
	// Deletes what can be downloaded again (runs, jobs, workflows, kept
	// logs); local run history, backups and recovery copies stay.
	ClearWorkspaceCache(context.Context, *ClearWorkspaceCacheRequest) (*ClearWorkspaceCacheResponse, error)
	// Deletes a workspace's whole folder; refused while it is open.
	DeleteWorkspaceData(context.Context, *DeleteWorkspaceDataRequest) (*DeleteWorkspaceDataResponse, error)
	// Whether completed jobs' logs are kept on this Mac. Off in every new Core.
	SetStoragePreferences(context.Context, *SetStoragePreferencesRequest) (*SetStoragePreferencesResponse, error)
	ListWorkflows(context.Context, *ListWorkflowsRequest) (*ListWorkflowsResponse, error)
	// Run Workflow presets the repository shares in .runnir/launches, read in
	// the same scan as its workflows. Runnir never writes these files.
	ListLaunchPresets(context.Context, *ListLaunchPresetsRequest) (*ListLaunchPresetsResponse, error)
	// Checks the workflow files on disk now with actionlint, built into the
	// Core; no external program runs and nothing is sent anywhere.
	ValidateWorkflows(context.Context, *ValidateWorkflowsRequest) (*ValidateWorkflowsResponse, error)
	// Saves a workflow file the user edited, replacing it in one rename. The
	// file is only written while it still has base_sha256, the digest of what
	// the editor loaded; otherwise the response reports a conflict and nothing
	// changes, unless overwrite is set. The repository is scanned again after
	// a save.
	SaveWorkflowFile(context.Context, *SaveWorkflowFileRequest) (*SaveWorkflowFileResponse, error)
	// Adds a workflow file to .github/workflows, making the folders when they
	// are missing, and scans the repository again. A name that is taken is
	// refused (ALREADY_EXISTS); no file is ever replaced.
	CreateWorkflowFile(context.Context, *CreateWorkflowFileRequest) (*CreateWorkflowFileResponse, error)
	// Renames a workflow file within .github/workflows and scans the
	// repository again. A name another file has is refused (ALREADY_EXISTS).
	RenameWorkflowFile(context.Context, *RenameWorkflowFileRequest) (*RenameWorkflowFileResponse, error)
	// The editor's text with the suggested concurrency block before the
	// top-level jobs key, or why it was not added. Writes nothing.
	InsertWorkflowConcurrency(context.Context, *InsertWorkflowConcurrencyRequest) (*InsertWorkflowConcurrencyResponse, error)
	// Starts an execution without a reviewed plan. Local runs need one, so
	// executions started this way fail; use PrepareLocalRun.
	StartWorkflow(context.Context, *StartWorkflowRequest) (*ExecutionResponse, error)
	SubscribeEvents(*SubscribeEventsRequest, grpc.ServerStreamingServer[CoreEvent]) error
	// The app hands the signed-in user's GitHub token to the Core's memory. It
	// is never written to disk, logged, sent in events or returned by any call.
	SetGitHubCredential(context.Context, *SetGitHubCredentialRequest) (*SetGitHubCredentialResponse, error)
	ClearGitHubCredential(context.Context, *ClearGitHubCredentialRequest) (*ClearGitHubCredentialResponse, error)
	// Asks GitHub what a token can do, without holding it: whether it is
	// accepted, its kind, and the rights Runnir needs that it has, lacks or
	// that GitHub does not show without trying a change. A refused token is
	// TOKEN_REJECTED in `status`; the held credential is never changed.
	CheckGitHubToken(context.Context, *CheckGitHubTokenRequest) (*CheckGitHubTokenResponse, error)
	// The signed-in user's open pull requests, each with the state of the
	// GitHub Actions runs on its head commit, and those closed since a time,
	// newest first, at most 50 of each, read through GitHub's search.
	ListPullRequests(context.Context, *ListPullRequestsRequest) (*ListPullRequestsResponse, error)
	// The github.com repository each folder's origin points at, read from git's
	// metadata only, without opening the repositories: lets the app match its
	// registered working trees to GitHub repositories. At most 500 paths.
	GetGitHubOrigins(context.Context, *GetGitHubOriginsRequest) (*GetGitHubOriginsResponse, error)
	// The github.com repositories the signed-in user's token reaches: those of
	// the accounts where the Runnir Desktop app is installed, up to 1,000.
	ListGitHubRepositories(context.Context, *ListGitHubRepositoriesRequest) (*ListGitHubRepositoriesResponse, error)
	// GitHub Actions data for a github.com repository, read with the token
	// from SetGitHubCredential: the one an open repository's origin points at
	// (repository_id), or any repository by name (github_repository) for one
	// without a local clone. GitHub-side problems are reported in `status`,
	// not as call errors.
	ListGitHubWorkflows(context.Context, *ListGitHubWorkflowsRequest) (*ListGitHubWorkflowsResponse, error)
	// The GitHub repository itself: whether the token can see it, and its
	// visibility and default branch.
	GetGitHubRepository(context.Context, *GetGitHubRepositoryRequest) (*GetGitHubRepositoryResponse, error)
	ListWorkflowRuns(context.Context, *ListWorkflowRunsRequest) (*ListWorkflowRunsResponse, error)
	ListRunJobs(context.Context, *ListRunJobsRequest) (*ListRunJobsResponse, error)
	// Branches and tags a workflow can run on.
	ListGitHubRefs(context.Context, *ListGitHubRefsRequest) (*ListGitHubRefsResponse, error)
	// Whether a workflow can be started by hand at a ref, and its inputs, read
	// from the workflow file on GitHub at that ref.
	DescribeWorkflowDispatch(context.Context, *DescribeWorkflowDispatchRequest) (*DescribeWorkflowDispatchResponse, error)
	// Starting a workflow takes two calls: Prepare validates and returns a
	// single-use confirmation that expires; only Confirm sends it to GitHub.
	PrepareWorkflowDispatch(context.Context, *PrepareWorkflowDispatchRequest) (*PrepareWorkflowDispatchResponse, error)
	ConfirmWorkflowDispatch(context.Context, *ConfirmWorkflowDispatchRequest) (*ConfirmWorkflowDispatchResponse, error)
	// The dispatches GitHub accepted from this Mac to the repository the origin
	// points at now, newest first, with the inputs that were sent except the
	// values that look secret (their names come back in omitted_inputs). At
	// most 200 are kept. Empty while the origin names no GitHub repository.
	// FAILED_PRECONDITION for a repository opened without a workspace_id.
	ListDispatchHistory(context.Context, *ListDispatchHistoryRequest) (*ListDispatchHistoryResponse, error)
	// Forgets that repository's dispatch history and says how many entries went.
	ClearDispatchHistory(context.Context, *ClearDispatchHistoryRequest) (*ClearDispatchHistoryResponse, error)
	// Says which run a history entry started, once the app has found it. The
	// first answer is kept; an unknown entry is not an error.
	LinkDispatchRun(context.Context, *LinkDispatchRunRequest) (*LinkDispatchRunResponse, error)
	// The end of one job's log (at most 2 MiB and 50,000 lines), split into
	// lines that are tagged with their kind and the step that wrote them.
	GetJobLog(context.Context, *GetJobLogRequest) (*GetJobLogResponse, error)
	// The whole log of one job (at most 256 MiB) written to a file in the
	// user's temporary folder, for an editor; the path is in the answer.
	SaveJobLog(context.Context, *SaveJobLogRequest) (*SaveJobLogResponse, error)
	// Cancelling or re-running a run takes two calls, like a dispatch: Prepare
	// checks the run's current state and returns a single-use confirmation;
	// only Confirm sends the request to GitHub, once.
	PrepareRunAction(context.Context, *PrepareRunActionRequest) (*PrepareRunActionResponse, error)
	ConfirmRunAction(context.Context, *ConfirmRunActionRequest) (*ConfirmRunActionResponse, error)
	// The programs local runs need, as found on this computer: the act bundled
	// with Runnir, an installed act, the Docker CLI and the container engine
	// of the current Docker context. Read-only: nothing is installed, started
	// or switched. The last result is reused unless refresh is set.
	GetToolReadiness(context.Context, *GetToolReadinessRequest) (*GetToolReadinessResponse, error)
	// Running a workflow locally takes two calls, like a dispatch: Prepare
	// checks the tools and the workflow file and returns the plan, with a
	// single-use confirmation when nothing blocks it; only Confirm starts act.
	PrepareLocalRun(context.Context, *PrepareLocalRunRequest) (*PrepareLocalRunResponse, error)
	ConfirmLocalRun(context.Context, *ConfirmLocalRunRequest) (*ConfirmLocalRunResponse, error)
	// A local run's state, job states and the output lines after a sequence
	// number. The Core keeps the last 5,000 lines of each of the last 20 runs.
	GetLocalRunOutput(context.Context, *GetLocalRunOutputRequest) (*GetLocalRunOutputResponse, error)
	// Stops a queued or running execution; a local run's containers are
	// removed afterwards.
	CancelExecution(context.Context, *CancelExecutionRequest) (*CancelExecutionResponse, error)
	// Parses a .env file the user chose, read by the app, to import values
	// into Secrets and Variables. Nothing is expanded or run; values
	// encrypted by dotenvx are flagged, not decrypted. INVALID_ARGUMENT for
	// content larger than 1 MiB or not UTF-8.
	ParseEnvFile(context.Context, *ParseEnvFileRequest) (*ParseEnvFileResponse, error)
	mustEmbedUnimplementedRunnirCoreServer()
}

